bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
const e=process.env;
const config={host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,
 password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:5000};
const pool=new pg.Pool({...config,database:e.VIDEOBOT_DB_NAME});
const outgoing=createCreatorTelegramFetch(globalThis.fetch);
try {
 const sources=await pool.query("SELECT datname FROM pg_database WHERE datallowconn AND NOT datistemplate ORDER BY datname");
 process.stdout.write('STK04_DATABASES='+sources.rows.map(x=>x.datname).filter(x=>/^(videobot|gaybbs|gateapp|postgres|gserver|telegram|gace)/i.test(x)).join(',')+'\n');
 const products=await pool.query("SELECT COUNT(*)::int AS n FROM videobot_sticker_products WHERE status='published'");
 const posts=await pool.query("SELECT status,COUNT(*)::int AS n FROM videobot_sticker_topic_posts GROUP BY status ORDER BY status");
 process.stdout.write('STK04_PUBLISHED_PRODUCT_COUNT='+products.rows[0].n+'\n');
 process.stdout.write('STK04_POST_RECEIPTS='+posts.rows.map(x=>x.status+':'+x.n).join(',')+'\n');
 const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
 const api=createTelegramBotApi({token,fetchImpl:outgoing.fetch,timeoutMs:25000});
 const me=await api('getMe',{});
 if(me?.is_bot!==true||String(me.username||'').toLowerCase()!=='createvdobot')
   throw Error('STK04_CREATEVDOBOT_IDENTITY_INVALID');
 const chat=await api('getChat',{chat_id:-1002373696859});
 if(chat?.id!==-1002373696859||chat?.type!=='supergroup'||chat?.is_forum!==true)
   throw Error('STK04_CHAT_NOT_FORUM');
 const member=await api('getChatMember',{chat_id:-1002373696859,user_id:me.id});
 process.stdout.write('STK04_CREATOR_MEMBER_ADMIN='+
   (['administrator','creator'].includes(member?.status)?'YES':'NO')+'\n');
 process.stdout.write('STK04_CREATOR_CHAT_VERIFIED=PASS\n');
 for (const dbName of sources.rows.map(x=>x.datname).filter(x=>/^(videobot|gaybbs|gateapp|postgres|gserver|telegram|gace)/i.test(x.datname))) {
   const other=new pg.Pool({...config,database:dbName});
   try {
     const table=await other.query("SELECT to_regclass('public.posting_topics') AS t");
     if(table.rows?.[0]?.t){
       const topics=await other.query("SELECT message_thread_id,title,enabled,verified_at IS NOT NULL AND verified_by IS NOT NULL AS verified FROM posting_topics WHERE board_key='video_chat' AND purpose='sticker' AND chat_id=-1002373696859");
       process.stdout.write('STK04_GATE_DB='+dbName+';TOPICS='+topics.rows.map(t=>String(t.message_thread_id)+':'+(t.verified&&t.enabled?'VERIFIED':'UNVERIFIED')).join(',')+'\n');
     }
   }catch{process.stdout.write('STK04_GATE_DB_CHECK_UNAVAILABLE='+dbName+'\n');}
   finally{await other.end();}
 }
}finally{await outgoing.close();await pool.end();}
NODE
